// IdentityProfileToEnvVar converts IdentityProfile to environment variable key-value pairs.
func IdentityProfileToEnvVar(v *IdentityProfile) map[string]string {
	if v == nil {
		return nil
	}
	result := make(map[string]string)
	result["PROTO_LIBS_SERVICENAME_IDENTITY_PROFILE_ID"] = v.Id
	if len(v.Sentinel) > 0 {
		parts := make([]string, len(v.Sentinel))
		for i, val := range v.Sentinel {
			parts[i] = SentinelServiceRPCsToString(val)
		}
		result["PROTO_LIBS_SERVICENAME_IDENTITY_PROFILE_SENTINEL"] = strings.Join(parts, ",")
	}
	if len(v.Identity) > 0 {
		parts := make([]string, len(v.Identity))
		for i, val := range v.Identity {
			parts[i] = IdentityServiceRPCsToString(val)
		}
		result["PROTO_LIBS_SERVICENAME_IDENTITY_PROFILE_IDENTITY"] = strings.Join(parts, ",")
	}
	if len(v.Policy) > 0 {
		parts := make([]string, len(v.Policy))
		for i, val := range v.Policy {
			parts[i] = PolicyServiceRPCsToString(val)
		}
		result["PROTO_LIBS_SERVICENAME_IDENTITY_PROFILE_POLICY"] = strings.Join(parts, ",")
	}
	if len(v.Policysim) > 0 {
		parts := make([]string, len(v.Policysim))
		for i, val := range v.Policysim {
			parts[i] = PolicySimServiceRPCsToString(val)
		}
		result["PROTO_LIBS_SERVICENAME_IDENTITY_PROFILE_POLICYSIM"] = strings.Join(parts, ",")
	}
	if len(v.Mcp) > 0 {
		parts := make([]string, len(v.Mcp))
		for i, val := range v.Mcp {
			parts[i] = McpAssistServiceRPCsToString(val)
		}
		result["PROTO_LIBS_SERVICENAME_IDENTITY_PROFILE_MCP"] = strings.Join(parts, ",")
	}
	return result
}

// IdentityProfileFromEnvVar creates IdentityProfile from environment variable key-value pairs.
func IdentityProfileFromEnvVar(env map[string]string) (*IdentityProfile, error) {
	result := &IdentityProfile{}
	if val, ok := env["PROTO_LIBS_SERVICENAME_IDENTITY_PROFILE_ID"]; ok && val != "" {
		result.Id = val
	}
	if val, ok := env["PROTO_LIBS_SERVICENAME_IDENTITY_PROFILE_SENTINEL"]; ok && val != "" {
		parts := strings.Split(val, ",")
		result.Sentinel = make([]SentinelServiceRPCs, 0, len(parts))
		for _, p := range parts {
			parsed, err := ParseSentinelServiceRPCs(strings.TrimSpace(p))
			if err != nil {
				return nil, err
			}
			result.Sentinel = append(result.Sentinel, parsed)
		}
	}
	if val, ok := env["PROTO_LIBS_SERVICENAME_IDENTITY_PROFILE_IDENTITY"]; ok && val != "" {
		parts := strings.Split(val, ",")
		result.Identity = make([]IdentityServiceRPCs, 0, len(parts))
		for _, p := range parts {
			parsed, err := ParseIdentityServiceRPCs(strings.TrimSpace(p))
			if err != nil {
				return nil, err
			}
			result.Identity = append(result.Identity, parsed)
		}
	}
	if val, ok := env["PROTO_LIBS_SERVICENAME_IDENTITY_PROFILE_POLICY"]; ok && val != "" {
		parts := strings.Split(val, ",")
		result.Policy = make([]PolicyServiceRPCs, 0, len(parts))
		for _, p := range parts {
			parsed, err := ParsePolicyServiceRPCs(strings.TrimSpace(p))
			if err != nil {
				return nil, err
			}
			result.Policy = append(result.Policy, parsed)
		}
	}
	if val, ok := env["PROTO_LIBS_SERVICENAME_IDENTITY_PROFILE_POLICYSIM"]; ok && val != "" {
		parts := strings.Split(val, ",")
		result.Policysim = make([]PolicySimServiceRPCs, 0, len(parts))
		for _, p := range parts {
			parsed, err := ParsePolicySimServiceRPCs(strings.TrimSpace(p))
			if err != nil {
				return nil, err
			}
			result.Policysim = append(result.Policysim, parsed)
		}
	}
	if val, ok := env["PROTO_LIBS_SERVICENAME_IDENTITY_PROFILE_MCP"]; ok && val != "" {
		parts := strings.Split(val, ",")
		result.Mcp = make([]McpAssistServiceRPCs, 0, len(parts))
		for _, p := range parts {
			parsed, err := ParseMcpAssistServiceRPCs(strings.TrimSpace(p))
			if err != nil {
				return nil, err
			}
			result.Mcp = append(result.Mcp, parsed)
		}
	}
	return result, nil
}

